<script setup>
import { onMounted, onBeforeUnmount, ref } from 'vue';
import { useAppStore } from '../../stores/appStore';
import { useCollabStore } from '../../stores/collabStore';
import { VideoCall } from '../../lib/realtimeCall';
import ShareLinkModal from '../modals/ShareLinkModal.vue';
const app=useAppStore(), store=useCollabStore();
const name=ref(''), error=ref(''), busy=ref(false), share=ref(''), inviteInput=ref('');
async function create() {if(!store.requireTeacher(create,'для создания видеозвонка')) return; busy.value=true; error.value=''; try {const result=await store.createCallRoom(); app.currentCallRoomId.value=result.roomId; app.currentCallKey.value=result.key; share.value=store.buildCallInviteLink(result.roomId,result.key);}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function join() {busy.value=true; error.value=''; try{await VideoCall.join(()=>store.getCallToken(app.currentCallRoomId.value,name.value.trim()||'Участник',app.currentCallKey.value));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function leave() {await VideoCall.leave(); app.currentCallRoomId.value=null; app.currentCallKey.value=null;}
function invite() {try {const u=new URL(inviteInput.value); const p=new URLSearchParams(u.search); const id=p.get('call'); if(!id||!p.get('key')) throw Error(); app.currentCallRoomId.value=id; app.currentCallKey.value=p.get('key'); error.value='';} catch {error.value='Вставьте полную ссылку-приглашение на звонок.';}}
onMounted(()=>VideoCall.init()); onBeforeUnmount(()=>{void VideoCall.leave();});
</script>
<template><section><div class="section-row"><div><h1 class="screen-title">Видеозвонки</h1><p class="screen-subtitle">Проводите занятия с камерой и демонстрацией экрана</p></div><div v-if="app.currentCallRoomId.value" class="actions"><button class="btn btn-secondary" @click="share=store.buildCallInviteLink(app.currentCallRoomId.value,app.currentCallKey.value)">Ссылка ученику</button><button class="btn btn-danger-soft" @click="leave">Закрыть комнату</button></div></div><div v-if="!app.currentCallRoomId.value" class="panel call-start"><h2>Начните занятие</h2><p>Создайте комнату или присоединитесь по приглашению.</p><button v-if="app.isTeacher.value" class="btn btn-accent" :disabled="busy" @click="create">{{busy?'Создаём…':'Создать видеозвонок'}}</button><form class="actions" @submit.prevent="invite"><input v-model="inviteInput" class="form-input" placeholder="Ссылка-приглашение" aria-label="Ссылка-приглашение на звонок" required /><button class="btn btn-secondary">Открыть</button></form></div><div v-show="app.currentCallRoomId.value"><div id="callJoinView" class="panel call-start"><h2>Присоединиться к звонку</h2><form class="actions" @submit.prevent="join"><input v-model="name" class="form-input" placeholder="Ваше имя" aria-label="Ваше имя" maxlength="40" required /><button class="btn btn-primary" :disabled="busy">{{busy?'Подключаемся…':'Присоединиться'}}</button></form></div><p id="callStatus" class="screen-subtitle" aria-live="polite" /><button id="resumeCallAudioBtn" class="btn btn-secondary" hidden>Включить звук</button><div id="callVideosWrap" class="hidden"><div id="videoGrid" class="video-grid" /></div><div id="callControls" class="call-controls hidden"><button id="toggleMicBtn" class="btn btn-secondary" title="Микрофон">Микрофон</button><button id="toggleCamBtn" class="btn btn-secondary" title="Камера">Камера</button><button id="shareScreenBtn" class="btn btn-secondary" title="Показать экран">Экран</button><button class="btn btn-danger" @click="leave">Завершить</button></div></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><ShareLinkModal v-if="share" :link="share" @close="share=''" /></section></template>
